def base_string_uri(uri: str, host: str=None) ->str:
    if not isinstance(uri, str):
        raise ValueError('uri must be a string')
    if not uri or uri.strip() == '':
        raise ValueError('uri is empty')
    uri = uri.strip()
    sch, netloc, path, par, query, fra = urlparse.urlparse(uri)
    if not sch:
        raise ValueError('uri has no scheme')
    sch = sch.lower()
    if host:
        netloc = host
    if not netloc:
        raise ValueError('uri has no host')
    netloc = netloc.lower()
    if netloc.startswith('['):
        bracket_end = netloc.find(']')
        if bracket_end == -1:
            raise ValueError('uri has invalid IPv6 address')
        ip_part = netloc[:bracket_end + 1]
        rest = netloc[bracket_end + 1:]
        if rest == '':
            pass
        elif rest.startswith(':'):
            port_part = rest[1:]
            if port_part == '':
                netloc = ip_part
            else:
                try:
                    port_num = int(port_part)
                except ValueError:
                    raise ValueError('uri has invalid port')
                if port_num <= 0 or port_num > 65535:
                    raise ValueError('uri has invalid port')
                if (sch == 'http' and port_num == 80) or (sch == 'https' and port_num == 443):
                    netloc = ip_part
                else:
                    netloc = ip_part + ':' + port_part
        else:
            raise ValueError('uri has invalid host')
    elif ':' in netloc:
        colon_count = netloc.count(':')
        if colon_count > 1:
            raise ValueError('uri has invalid host')
        host_part, port_part = netloc.split(':', 1)
        if not host_part:
            raise ValueError('uri has no host')
        if port_part == '':
            netloc = host_part
        else:
            try:
                port_num = int(port_part)
            except ValueError:
                raise ValueError('uri has invalid port: ' + port_part)
            if port_num <= 0 or port_num > 65535:
                raise ValueError('uri has invalid port')
            if (sch == 'http' and port_num == 80) or (sch == 'https' and port_num == 443):
                netloc = host_part
            else:
                netloc = host_part + ':' + port_part
    if not netloc:
        raise ValueError('uri has no host')
    if not path:
        path = '/'
    path = urlparse.quote(urlparse.unquote(path), safe='/-._~!$&\'()*+,;=:@%')
    netloc_encoded = urlparse.quote(netloc, safe='[]:-._~!$&\'()*+,;=@%')
    result = urlparse.urlunparse((sch, netloc_encoded, path, '', '', ''))
    return result
```

